using System.Collections;
using UnityEngine;

/// <summary>
/// Spawn at a ground impact point. A warning marks the spot, then the 
/// lightning VFX strikes once. No lightning geometry is generated by code.
/// </summary>
public class ZeusLightningStrike : MonoBehaviour
{
    [Header("Timing")]
    [Min(0.1f)] public float warningSeconds = 1.5f;
    [Min(0f)] public float lingeringSeconds = 0.25f;

    [Header("Impact")]
    [Min(0.1f)] public float blastRadius = 2.4f;
    [Min(0f)] public float damage = 12f;
    [Min(0f)] public float knockback = 7f;
    public LayerMask playerLayers = ~0;

    [Header("VFX prefabs")]
    public GameObject warningCirclePrefab;
    public GameObject lightningBoltPrefab;
    public GameObject groundImpactPrefab;
    [Min(0.1f)] public float effectsLifetime = 4f;

    private IEnumerator Start()
    {
        GameObject warning = Spawn(warningCirclePrefab, transform.position);
        yield return new WaitForSeconds(warningSeconds);
        if (warning != null) Destroy(warning);

        Spawn(lightningBoltPrefab, transform.position);
        Spawn(groundImpactPrefab, transform.position);
        ApplyImpact();

        yield return new WaitForSeconds(lingeringSeconds);
        Destroy(gameObject);
    }

    private GameObject Spawn(GameObject prefab, Vector3 at)
    {
        if (prefab == null) return null;
        GameObject instance = Instantiate(prefab, at, transform.rotation);
        Destroy(instance, effectsLifetime);
        return instance;
    }

    private void ApplyImpact()
    {
        Collider[] hits = Physics.OverlapSphere(transform.position,
            blastRadius, playerLayers, QueryTriggerInteraction.Collide);
        foreach (Collider col in hits)
        {
            PlayerDurability player = col.GetComponentInParent<PlayerDurability>();
            if (player == null) continue;
            Vector3 away = player.transform.position - transform.position;
            away.y = 0.3f;
            player.TakeDamage(damage, away.normalized * knockback);
            break;
        }
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, blastRadius);
    }
}
